import { splitIntoBlocks } from './cleanup-code'
import {
	getDesignSystemIdsFromMarkdown,
	getFunctionIdsFromMarkdown,
	getIntegrationsFromPrompt
} from './composition'
import { isStatusIndicatingRevisionIsBuilding } from './project-revision'
import { Block, type Edge, Item, ProjectGroupRevisionAction } from './types'

const hideCommandActions: ProjectGroupRevisionAction[] = [
	ProjectGroupRevisionAction.PUBLISH_PROJECT_AND_CONTINUE_CHAT,
	ProjectGroupRevisionAction.SAVE_SECRET_AND_CONTINUE_CHAT
]

const buildBlocksForCommand = (node: Edge['node']): Block[] => {
	if (!node.chat) {
		return []
	}
	if (
		node.action === ProjectGroupRevisionAction.FORK_MODULE_WITH_CHAT_MESSAGE
	) {
		const [moduleId] = getFunctionIdsFromMarkdown(node.chat.content)
		if (moduleId) {
			// we only want to show the selected module
			return [
				{
					type: 'selected-module',
					moduleId
				}
			]
		}
	} else if (
		node.action ===
		ProjectGroupRevisionAction.SELECT_INTEGRATION_WITH_CHAT_MESSAGE
	) {
		const [integration] = getIntegrationsFromPrompt(node.chat.content)
		if (integration) {
			// we only want to show the selected integration
			return [
				{
					type: 'selected-integration',
					integration: integration
				}
			]
		}
	} else if (
		node.action ===
		ProjectGroupRevisionAction.CHANGE_DESIGN_SYSTEM_AND_CONTINUE_CHAT
	) {
		const [designSystemId] = getDesignSystemIdsFromMarkdown(node.chat.content)
		if (designSystemId) {
			return [
				{
					type: 'selected-design-system',
					designSystemId
				}
			]
		}
		return []
	}

	return splitIntoBlocks(node.chat.content).map((block) => ({
		code: block.type === 'tag' ? '' : block.content,
		lang: block.type === 'code' ? block.language ?? 'unknown' : 'unknown',
		isPartial: false,
		type: block.type === 'tag' ? 'text' : block.type
	}))
}

export const buildCommand = ({
	node,
	latestRevisionId
}: {
	node: Edge['node']
	latestRevisionId: string | null
}): Item | null => {
	if (!node.chat || hideCommandActions.includes(node.action)) {
		return null
	}

	return {
		type: 'message',
		data: {
			id: node.id,
			blocks: buildBlocksForCommand(node),
			actor: 'user' as const,
			action: null,
			isLatest: node.id === latestRevisionId,
			isGenerating:
				node.id === latestRevisionId &&
				isStatusIndicatingRevisionIsBuilding(node.status),
			revision:
				node.__typename === 'ProjectGroupRevision'
					? {
							type: 'project-group',
							id: node.id,
							createdAt: new Date(node.createdAt),
							previewURL: node.previewURL ?? null,
							status: node.status
					  }
					: null
		}
	}
}
